 "decisions": [
  {
   "title": "Data migrates to the Oracle target database",
   "context": "The target keeps its data in Oracle, while the legacy tables live in Sybase databases db_pagos, db_admin and db_cuentas.",
   "decision": "Use data_strategy migration: pg_orden, ad_tarifa_empresa, ad_servicio and ct_cuenta are migrated to the target Oracle database with unqualified snake_case table names and the same columns. Money columns keep the legacy precision as NUMBER(19,4).",
   "consequences": "A data migration and reconciliation of the four tables is required before go-live. The service no longer depends on the legacy databases at runtime."
  },
  {
   "title": "Debit logic is reimplemented in the target against migrated accounts",
   "context": "The legacy calls db_cuentas..sp_debito, which updates the account and returns a movement sequence. With the data migrated, that procedure no longer runs next to the data.",
   "decision": "DebitGateway is implemented in the target as an adapter over the migrated account data, with the same contract as sp_debito: it receives account, type, amount and reference, returns the movement sequence and fails when the debit cannot be applied. The port keeps legacy_program for replaying the golden master.",
   "consequences": "The business behaviour of sp_debito (validations, movement numbering) must be specified and verified by the reviewer, as it is not part of the approved rules. Other legacy consumers of sp_debito are outside the scope of this service."
  },
  {
   "title": "Single transaction from the first debit to the order update",
   "context": "The legacy opens the transaction at line 108 after all validations, and rolls back at three points (lines 119, 136, 155), committing at line 161.",
   "decision": "The PayOrder use case is one unit of work in the target Oracle database. Validations and calculations run before it begins. The debit, the optional commission debit and the order update run inside, and the debit adapter participates in the same transaction. Any failure rolls back everything and rejects with the matching error code: DEBIT_FAILED, COMMISSION_FAILED or ORDER_UPDATE_FAILED. There are no savepoints.",
   "consequences": "A debit is never kept if the commission or the order update fails. This holds only because accounts and orders are in the same database. Rejections before the transaction do not roll back anything because nothing has been written yet."
  },
  {
   "title": "Failure of the debit mapped by the gateway",
   "context": "The legacy treats a non-zero return code of sp_debito (or @@error) as a failure, and reads the movement sequence from the output parameter @o_secuencial.",
   "decision": "DebitGateway.debit returns the movement sequence and raises a failure when the debit is not applied. The use case maps that failure to DEBIT_FAILED for the order debit and to COMMISSION_FAILED for the separate commission debit. The commission call ignores the returned sequence.",
   "consequences": "Return-code plumbing is not translated. Exceptions replace it."
  },
  {
   "title": "Validation order and early rejection preserved",
   "context": "The legacy evaluates account type, order existence, order status, tariff, commission, total and funds in that order, and the first failing check wins.",
   "decision": "The use case keeps the same order of checks, so the same error is produced for the same input.",
   "consequences": "Error precedence is identical to the legacy."
  },
  {
   "title": "Monetary arithmetic and rounding",
   "context": "The legacy computes with money (4 decimals) and uses round(@w_tarifa / 2, 2) for the WEB channel.",
   "decision": "Use BigDecimal with scale 4 for amounts. The WEB commission is the tariff divided by 2 and rounded to 2 decimals with HALF_UP, then stored with scale 4. A NULL tariff becomes 0, and the NOMINA service always yields commission 0.",
   "consequences": "Results match the legacy for amounts with up to 4 decimals. The separate-charge flag is 'N' when the tariff comes from the service default."
  },
  {
   "title": "Missing account row behaves as in the legacy",
   "context": "If the balance lookup returns no row, @w_saldo stays NULL and the funds comparison is not true, so the legacy does not reject with 50004 and goes on to the debit.",
   "decision": "An empty result from AccountRepository is treated as an unknown balance: the funds check does not reject, and the debit is attempted, where the debit adapter decides.",
   "consequences": "This legacy behaviour is kept on purpose. The reviewer may decide to reject unknown accounts in a later change."
  },
  {
   "title": "Channel default and error logging",
   "context": "@i_canal defaults to 'WEB' in the legacy, and errors are logged through cobis..sp_cerror.",
   "decision": "If the channel is not provided, the use case uses 'WEB'. cobis..sp_cerror is infrastructure and is not translated: the error code and message are returned by the HTTP layer and logged by the framework.",
   "consequences": "No call to sp_cerror from the new service."
  }
 ],
