package com.bank.payments.adapters.out.jdbc;

import com.bank.payments.domain.model.CompanyTariff;
import com.bank.payments.domain.port.CompanyTariffRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

@Repository
public class JdbcCompanyTariffRepository implements CompanyTariffRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcCompanyTariffRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<CompanyTariff> findByCompanyAndService(Integer empresa, String servicio) {
        List<CompanyTariff> rows = jdbcTemplate.query(
                "SELECT tar_empresa, tar_servicio, tar_valor, tar_separada "
                        + "FROM ad_tarifa_empresa WHERE tar_empresa = ? AND tar_servicio = ? "
                        + "FETCH FIRST 1 ROWS ONLY",
                (rs, rowNum) -> new CompanyTariff(
                        rs.getInt("tar_empresa"),
                        rs.getString("tar_servicio"),
                        rs.getBigDecimal("tar_valor"),
                        rs.getString("tar_separada")),
                empresa, servicio);
        return rows.stream().findFirst();
    }
}
